// Pegar en nodo "Filtrar activas" (Run Once for All Items)
// Acepta columnas con nombre (URL, CSS_Selector…) o letras A–I si Sheets no lee encabezados.

function pick(row, ...keys) {
  for (const k of keys) {
    if (row[k] !== undefined && row[k] !== null && String(row[k]).trim() !== '') {
      return row[k];
    }
  }
  const entries = Object.entries(row);
  for (const want of keys) {
    const found = entries.find(([k]) => k.toLowerCase() === String(want).toLowerCase());
    if (found && found[1] !== undefined && found[1] !== null && String(found[1]).trim() !== '') {
      return found[1];
    }
  }
  return '';
}

function normalize(row) {
  return {
    ...row,
    Nombre: String(pick(row, 'Nombre', 'A', 'nombre') || 'Página').trim(),
    URL: String(pick(row, 'URL', 'B', 'url')).trim(),
    CSS_Selector: String(pick(row, 'CSS_Selector', 'C', 'css_selector')).trim(),
    Condicion: String(pick(row, 'Condicion', 'D', 'condicion') || 'changed').trim(),
    Valor_Umbral: String(pick(row, 'Valor_Umbral', 'E', 'valor_umbral')).trim(),
    Render_JS: String(pick(row, 'Render_JS', 'F', 'render_js') || 'NO').trim(),
    Activo: String(pick(row, 'Activo', 'G', 'activo') || 'SI').trim(),
    Ultimo_Valor: String(pick(row, 'Ultimo_Valor', 'H', 'ultimo_valor')).trim(),
    Ultima_Comprobacion: String(pick(row, 'Ultima_Comprobacion', 'I', 'ultima_comprobacion')).trim(),
    row_number: row.row_number,
  };
}

const rows = $input.all().map((item) => normalize(item.json));

const activas = rows.filter((row) => {
  if (!row.URL) return false;
  if (/^url$/i.test(row.URL)) return false; // fila de encabezados leída como dato
  if (!row.CSS_Selector) return false;
  if (/^css[_ ]?selector$/i.test(row.CSS_Selector)) return false;
  const activo = row.Activo.toUpperCase();
  return activo === 'SI' || activo === 'SÍ' || activo === 'TRUE' || activo === '1' || activo === 'ACTIVO';
});

if (activas.length === 0) {
  const muestra = $input.first()?.json ?? {};
  const claves = Object.keys(muestra).join(', ') || '(sin datos)';
  throw new Error(
    `No hay URLs activas. Claves recibidas: ${claves}. ` +
      'Añade al menos una fila de datos (fila 2+) con URL, CSS_Selector y Activo=SI. ' +
      'Fila 1 = encabezados.',
  );
}

return activas.map((row) => ({ json: row }));

// Pegar en nodo "Evaluar alerta" (Run Once for All Items)
// Compatible con precios ES: 1.199,00€ → 1199

const fila = $('Iterar URLs').item.json;
const extraidoRaw = $input.first().json.valor;
const extraido = Array.isArray(extraidoRaw)
  ? extraidoRaw.join(' | ')
  : String(extraidoRaw ?? '').trim();

const condicion = String(fila.Condicion ?? 'changed').trim().toLowerCase();
const umbral = String(fila.Valor_Umbral ?? '').trim();
const anterior = String(fila.Ultimo_Valor ?? '').trim();
const esBaseline =
  anterior === '' || anterior.toLowerCase() === 'pendiente';

/** Interpreta 1.199,00€ / 1199,00 € / £51.77 */
function parseNumero(text) {
  let s = String(text).replace(/\s/g, '').replace(/[€$£]|EUR/gi, '');
  // Miles ES: 1.199,00 o 1.199
  if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (/^\d+,\d+$/.test(s)) {
    s = s.replace(',', '.');
  } else {
    // £51.77 u otros: deja el primer número “simple”
    const m = s.match(/-?\d+(?:[.,]\d+)?/);
    if (!m) return Number.NaN;
    s = m[0].replace(',', '.');
  }
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : Number.NaN;
}

let alerta = false;
let motivo = '';

if (condicion === 'contains') {
  alerta = extraido.toLowerCase().includes(umbral.toLowerCase());
  motivo = `El texto extraído contiene «${umbral}»`;
} else if (condicion === 'not_contains') {
  alerta =
    extraido !== '' &&
    !extraido.toLowerCase().includes(umbral.toLowerCase());
  motivo = `El texto extraído no contiene «${umbral}»`;
} else if (condicion === 'smaller_than') {
  const n = parseNumero(extraido);
  const u = parseNumero(umbral);
  alerta = Number.isFinite(n) && Number.isFinite(u) && n < u;
  motivo = alerta
    ? `Precio ${n} < umbral ${u}`
    : `Precio ${n} no es < umbral ${u}`;
} else if (condicion === 'greater_than') {
  const n = parseNumero(extraido);
  const u = parseNumero(umbral);
  alerta = Number.isFinite(n) && Number.isFinite(u) && n > u;
  motivo = alerta
    ? `Precio ${n} > umbral ${u}`
    : `Precio ${n} no es > umbral ${u}`;
} else {
  const n = parseNumero(extraido);
  const a = parseNumero(anterior);
  if (Number.isFinite(n) && Number.isFinite(a)) {
    alerta = !esBaseline && n !== a;
  } else {
    alerta = !esBaseline && extraido !== anterior;
  }
  motivo = 'El valor extraído ha cambiado respecto a la última comprobación';
}

return [
  {
    json: {
      nombre: String(fila.Nombre ?? 'Página').trim(),
      url: String(fila.URL ?? '').trim(),
      selector: String(fila.CSS_Selector ?? '').trim(),
      extraido,
      anterior,
      alerta,
      motivo,
      condicion,
      umbral,
      ahora: new Date().toLocaleString('es-ES'),
      row_number: fila.row_number,
    },
  },
];

